const fs = require('fs');
const path = require('path');
const AWS = require('aws-sdk');

// Lambda handler for serving static documentation files
// Files are bundled in the Lambda deployment package under /var/task/docs/
exports.handler = async (event) => {
  const requestedFile = event.queryStringParameters?.file;

  if (!requestedFile) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: 'Missing file parameter' })
    };
  }

  // Basic extension whitelist check
  const allowedExtensions = ['.md', '.txt', '.html', '.json'];
  const ext = path.extname(requestedFile).toLowerCase();

  if (!allowedExtensions.includes(ext)) {
    return {
      statusCode: 403,
      body: JSON.stringify({ error: 'File type not permitted' })
    };
  }

  // Construct the file path relative to docs directory
  const docsBase = '/var/task/docs';
  const filePath = path.join(docsBase, requestedFile);

  // NOTE: path.join resolves '..' segments, but does NOT prevent traversal
  // outside the base directory. We rely on the extension check above.

  try {
    const content = fs.readFileSync(filePath, 'utf-8');

    // Log access for audit trail
    console.log(JSON.stringify({
      action: 'file_read',
      path: filePath,
      requestId: event.requestContext?.requestId,
      sourceIp: event.requestContext?.identity?.sourceIp,
      timestamp: new Date().toISOString()
    }));

    return {
      statusCode: 200,
      headers: { 'Content-Type': getMimeType(ext) },
      body: content
    };
  } catch (err) {
    if (err.code === 'ENOENT') {
      return {
        statusCode: 404,
        body: JSON.stringify({ error: 'File not found' })
      };
    }
    console.error('Read error:', err.message);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal server error' })
    };
  }
};

function getMimeType(ext) {
  const types = {
    '.md': 'text/markdown',
    '.txt': 'text/plain',
    '.html': 'text/html',
    '.json': 'application/json'
  };
  return types[ext] || 'application/octet-stream';
}

// Health check endpoint used by internal monitoring
exports.health = async () => {
  return {
    statusCode: 200,
    body: JSON.stringify({ status: 'ok', runtime: process.version })
  };
};
